import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, Shape, ExtrudeGeometry, PlaneGeometry, PointLight, AmbientLight } = ctx.THREE;

  const group = new Group();
  const cleanupTasks = [];

  // 1. Resolve Spec Colors
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 2. Subtle local backdrop to prevent FLAT_VOID and ground the element
  const backdropGeo = new PlaneGeometry(2.5, 1.2);
  const backdropMat = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.85
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.05);
  group.add(backdrop);

  // 3. Create the machined-metal capsule container
  const shape = new Shape();
  const width = 1.4;
  const height = 0.5;
  const radius = 0.25;

  // Draw capsule
  shape.absarc(-width / 2 + radius, 0, radius, Math.PI / 2, Math.PI * 1.5, false);
  shape.absarc(width / 2 - radius, 0, radius, Math.PI * 1.5, Math.PI / 2, false);

  const extrudeSettings = {
    depth: 0.05,
    bevelEnabled: true,
    bevelSegments: 4,
    steps: 1,
    bevelSize: 0.015,
    bevelThickness: 0.015
  };

  const capsuleGeo = new ExtrudeGeometry(shape, extrudeSettings);
  capsuleGeo.center();

  // Machined-metal PBR material
  const capsuleMat = new MeshStandardNodeMaterial({
    color: colors.ink,
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1
  });

  const capsuleMesh = new Mesh(capsuleGeo, capsuleMat);
  group.add(capsuleMesh);

  // 4. Accent Edge Light (glow border slightly scaled up behind capsule)
  const edgeGeo = new ExtrudeGeometry(shape, {
    ...extrudeSettings,
    depth: 0.03,
    bevelSize: 0.02,
    bevelThickness: 0.02
  });
  edgeGeo.center();

  const edgeMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.8,
    roughness: 0.1
  });

  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.set(0, 0, -0.01);
  group.add(edgeMesh);

  // 5. Load GLB Mesh (gear-a.glb) as ornamental feature
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const gear = gltf.scene;
      gear.scale.setScalar(0.08);
      // Place it at the left of the capsule
      gear.position.set(-width / 2, 0, 0.04);

      // Apply metallic styling to match machined gear
      gear.traverse((node) => {
        if (node.isMesh) {
          node.material = new MeshStandardNodeMaterial({
            color: colors.paper,
            metalness: 0.9,
            roughness: 0.2
          });
        }
      });
      group.add(gear);

      // Micro idle rotation
      const rotateAnim = gsap.to(gear.rotation, {
        z: Math.PI * 2,
        duration: 12,
        repeat: -1,
        ease: 'none'
      });
      cleanupTasks.push(() => rotateAnim.kill());
    }).catch(err => console.error("Failed loading gear mesh", err));
  }

  // 6. Text Rendering
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelText = items[0]?.text ?? "JOURNAL";

  const textObj = ctx.fontAtlas.createText(labelText.toUpperCase(), {
    fontSize: 22,
    color: colors.paper,
    align: 'center'
  });
  // Position text over the capsule face
  textObj.position.set(0.08, -0.04, 0.06);
  textObj.scale.setScalar(0.0035);
  group.add(textObj);

  // Local light rigs
  const keyLight = new PointLight(colors.accent, 1.2, 5);
  keyLight.position.set(1.5, 1, 1);
  group.add(keyLight);

  const fillLight = new AmbientLight(colors.paper, 0.4);
  group.add(fillLight);

  // 7. Interactive Handlers
  let isHovered = false;
  let activeTimeline = null;

  group.userData.handlers = {
    pointerover: () => {
      isHovered = true;
      if (activeTimeline) activeTimeline.kill();

      activeTimeline = gsap.timeline();
      activeTimeline.to(group.position, {
        y: config.scenePosition?.[1] !== undefined ? config.scenePosition[1] + 0.15 : 0.15,
        duration: 0.3,
        ease: 'power2.out'
      });
      activeTimeline.to(edgeMesh.scale, {
        x: 1.05,
        y: 1.05,
        duration: 0.3,
        ease: 'power2.out'
      }, 0);
    },
    pointerout: () => {
      isHovered = false;
      if (activeTimeline) activeTimeline.kill();

      activeTimeline = gsap.timeline();
      activeTimeline.to(group.position, {
        y: config.scenePosition?.[1] !== undefined ? config.scenePosition[1] : 0,
        duration: 0.5,
        ease: 'power4.out'
      });
      activeTimeline.to(edgeMesh.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.5,
        ease: 'power4.out'
      }, 0);
    },
    click: () => {
      ctx.emit('hub-journal.select', { id: config.id });

      // Press recoil animation
      gsap.timeline()
        .to(group.scale, { x: 0.92, y: 0.92, duration: 0.1, ease: 'back.out' })
        .to(group.scale, { x: 1, y: 1, duration: 0.2, ease: 'power2.out' });
    }
  };

  // Entrance animation (weighted settle)
  group.scale.setScalar(0.2);
  const entrance = gsap.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  });
  cleanupTasks.push(() => entrance.kill());

  // 8. Apply Cinematic Primitives
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const inst = ctx.primitives[prim.name](group, prim.params);
        if (inst && inst.cleanup) {
          cleanupTasks.push(inst.cleanup);
        }
      }
    });
  }

  // Cleanup Hook
  group.userData.cleanup = () => {
    if (activeTimeline) activeTimeline.kill();
    cleanupTasks.forEach((task) => task());
    capsuleGeo.dispose();
    capsuleMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
  };

  return group;
}
